import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.json.*;

public class InventoryServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String category = req.getParameter("category");
        String sortCol = req.getParameter("sort");
        String warehouse = req.getParameter("warehouse_id");

        if (category == null) {
            resp.sendError(400, "category required");
            return;
        }

        // Validate sort column against allowlist
        List<String> allowedSorts = Arrays.asList("name", "price", "quantity", "updated_at");
        if (sortCol == null || !allowedSorts.contains(sortCol)) {
            sortCol = "name";
        }

        StringBuilder sql = new StringBuilder();
        sql.append("SELECT id, name, price, quantity, updated_at FROM inventory WHERE category = '");
        sql.append(category);
        sql.append("'");

        if (warehouse != null && !warehouse.isEmpty()) {
            sql.append(" AND warehouse_id = '");
            sql.append(warehouse);
            sql.append("'");
        }

        sql.append(" ORDER BY ").append(sortCol).append(" ASC");

        resp.setContentType("application/json");
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql.toString())) {

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject item = new JSONObject();
                item.put("id", rs.getInt("id"));
                item.put("name", rs.getString("name"));
                item.put("price", rs.getDouble("price"));
                item.put("quantity", rs.getInt("quantity"));
                item.put("updated_at", rs.getString("updated_at"));
                results.put(item);
            }
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String body = new String(req.getInputStream().readAllBytes());
        JSONObject payload = new JSONObject(body);

        String name = payload.optString("name");
        String category = payload.optString("category");
        double price = payload.optDouble("price", 0.0);
        int quantity = payload.optInt("quantity", 0);
        String warehouseId = payload.optString("warehouse_id");

        String insertSql = "INSERT INTO inventory (name, category, price, quantity, warehouse_id) VALUES ('" 
            + name + "', '" + category + "', " + price + ", " + quantity + ", '" + warehouseId + "')";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {
            stmt.executeUpdate(insertSql);
            resp.setStatus(201);
            resp.getWriter().write("{\"status\":\"created\"}");
        } catch (SQLException e) {
            resp.sendError(500, "Insert failed: " + e.getMessage());
        }
    }

    @Override
    protected void doDelete(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String id = req.getParameter("id");
        if (id == null) {
            resp.sendError(400, "id required");
            return;
        }
        String deleteSql = "DELETE FROM inventory WHERE id = " + id;
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {
            int affected = stmt.executeUpdate(deleteSql);
            resp.getWriter().write("{\"deleted\":" + affected + "}");
        } catch (SQLException e) {
            resp.sendError(500, "Delete failed");
        }
    }
}
